#include "ksFirmwareLayoutCheckCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{FirmwareLayoutCheckPartialTest partialTest=nullptr;using T=FirmwareLayoutCheckTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::LocateEnd:return{0x540,6};case S::ComputeExtent:return{0x546,6};case S::AdmitExtent:return{0x54c,2};case S::Finish:return{0x560,2};default:throw std::runtime_error("Invalid firmware layout check stage");}}}
bool FirmwareLayoutCheckCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0x540){if(selected)throw std::runtime_error("Overlapping firmware layout check");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Firmware layout check capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto cost=t.nextClocks();t.advanceBefore(cost);switch(stage){case S::LocateEnd:f.move(h.regs[0].er,0x15540);break;case S::ComputeExtent:h.regs[0].er=h.sub32(h.regs[0].er,0x1537a);if(uint32_t(h.regs[0].er)!=t.extent())throw std::runtime_error("Firmware layout check extent projection differs");break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Firmware layout check clocks differ");return true;}}

namespace ks{void setFirmwareLayoutCheckPartialForTests(FirmwareLayoutCheckPartialTest fn){partialTest=fn;}}
